// Poner automaticamente el salerOrder id
[FormDataSourceEventHandler(formDataSourceStr(SalesTable, AIBSalesResponsible), FormDataSourceEventType::Created)]
public static void AIBSalesResponsible_OnCreated(FormDataSource sender, FormDataSourceEventArgs e)
{
    AIBSalesResponsible responsibleBuffer = sender.cursor();

    FormDataSource salesTable_ds = sender.formRun().dataSource(formDataSourceStr(SalesTable, SalesTable));
    SalesTable salesTable = salesTable_ds.cursor();

    responsibleBuffer.SalesId = salesTable.SalesId;
}

// Add
[FormControlEventHandler(formControlStr(SalesTable, AIBResponsibleAdd), FormControlEventType::Clicked)]
public static void AIBResponsibleAdd_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormDataSource responsible_ds = sender.formRun().dataSource(formDataSourceStr(SalesTable, AIBSalesResponsible));
    responsible_ds.create();
}

// Delete
[FormControlEventHandler(formControlStr(SalesTable, AIBResponsibleDelete), FormControlEventType::Clicked)]
public static void AIBResponsibleDelete_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormDataSource responsible_ds = sender.formRun().dataSource(formDataSourceStr(SalesTable, AIBSalesResponsible));
    responsible_ds.delete();

}
